function filteredExpenses(){const q=$('expenseSearch').value.toLocaleLowerCase('pt-BR'),st=$('expenseStatus').value,p=$('expensePerson').value;return expenses.filter(x=>(!st||x.status===st)&&(!p||String(x.paid_by_user_id)===p)&&(!q||[x.description,x.vendor_name,x.vendor_document,user(x.paid_by_user_id),by(events,x.event_id,'event_id')?.name].some(v=>String(v||'').toLocaleLowerCase('pt-BR').includes(q)))).sort((a,b)=>{const x=a[sortKey],y=b[sortKey];if(typeof x==='number'||typeof y==='number')return(Number(x||0)-Number(y||0))*sortDir;return String(x||'').localeCompare(String(y||''),'pt-BR',{numeric:true,sensitivity:'base'})*sortDir})}
