function reimbursementForm(){const eligible=expenses.filter(x=>Number(x.pending_amount)>0&&['AGUARDANDO_REEMBOLSO','PARCIALMENTE_REEMBOLSADA','APROVADA'].includes(x.status)),people=[...new Set(eligible.map(x=>x.paid_by_user_id))];$('modalTitle').textContent='Registrar reembolso';$('modalBody').innerHTML=`<div class="form"><div class="field"><label>Empresa *</label><select id="rCompany">${opts(B.companies,'key','name')}</select></div><div class="field"><label>Pessoa *</label><select id="rPerson"><option value="">Selecione…</option>${people.map(id=>`<option value="${id}">${esc(user(id))}</option>`).join('')}</select></div><div class="field"><label>Data</label><input id="rDate" type="datetime-local"></div><div class="field"><label>Forma de pagamento</label><input id="rMethod" placeholder="Pix, transferência…"></div><div class="field"><label>Banco</label><input id="rBank"></div><div class="field"><label>Identificação</label><input id="rTx"></div><div class="field full"><label>Despesas</label><div id="rItems"></div></div><div class="field full"><label>Observações</label><textarea id="rNotes"></textarea></div></div>`;$('modalActions').innerHTML='<button class="btn" id="modalClose">Cancelar</button><button class="btn primary" id="saveReimbursement">Registrar</button>';showModal();$('rCompany').value=currentCompany()||B.companies[0]?.key||'';$('rDate').value=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);const draw=()=>{const c=$('rCompany').value,p=$('rPerson').value,xs=eligible.filter(x=>x.company_key===c&&String(x.paid_by_user_id)===p);$('rItems').innerHTML=xs.map(x=>`<label class="reimb-row"><input type="checkbox" data-ri="${x.expense_id}"><span>${esc(x.description)}<small>${money(x.pending_amount)} pendente</small></span><input data-rv="${x.expense_id}" type="number" step="0.01" min="0" max="${x.pending_amount}" value="${Number(x.pending_amount).toFixed(2)}"></label>`).join('')||'<div class="empty">Sem despesas elegíveis.</div>'};$('rCompany').onchange=draw;$('rPerson').onchange=draw;$('modalClose').onclick=hideModal;$('saveReimbursement').onclick=async()=>{const items=[...document.querySelectorAll('[data-ri]:checked')].map(ch=>({expense_id:ch.dataset.ri,amount:Number(document.querySelector(`[data-rv="${ch.dataset.ri}"]`).value)}));if(!items.length)return alert('Selecione ao menos uma despesa.');await api('/reimbursements',{method:'POST',body:JSON.stringify({company_key:$('rCompany').value,payee_user_id:$('rPerson').value,paid_at:new Date($('rDate').value).toISOString(),payment_method:$('rMethod').value,bank_name:$('rBank').value,transaction_id:$('rTx').value,notes:$('rNotes').value,items,idempotency_key:crypto.randomUUID()})});hideModal();await reload();flash('Reembolso registrado.')}}
function catalogDefs(){return[{label:'Categorias',type:'category',rows:B.categories,id:'category_id'},{label:'Centros de custo',type:'cost_center',rows:B.costCenters,id:'cost_center_id'},{label:'Projetos',type:'project',rows:B.projects,id:'project_id'},{label:'Formas de pagamento',type:'payment_method',rows:B.paymentMethods,id:'payment_method_id'}]}
function renderCatalogs(){const allDefs=catalogDefs(),defs=B.permissions.admin?allDefs:[],valid=B.permissions.admin?[...defs.map(x=>x.type),'cards']:['cards'];if(!valid.includes(catalogTab))catalogTab='cards';const tabs=(B.permissions.admin?defs.map(d=>`<button class="catalog-tab ${catalogTab===d.type?'active':''}" data-cat-tab="${d.type}">${d.label}</button>`).join(''):'')+`<button class="catalog-tab ${catalogTab==='cards'?'active':''}" data-cat-tab="cards">Cartões</button>`;let panel='';if(catalogTab==='cards'){const visible=cards.filter(c=>c.card_type==='PESSOAL'||!currentCompany()||c.company_key===currentCompany());panel=`<div class="catalog-panel"><div class="catalog-panel-head"><div class="grow"><h3>Cartões</h3><small>Cartão pessoal é privado. Cartões da empresa aparecem somente para quem recebeu acesso.</small></div><button class="btn" id="addPersonalCard">+ Pessoal</button>${B.permissions.admin?'<button class="btn primary" id="addCompanyCard">+ Empresa</button>':''}</div>${visible.map(c=>`<div class="catalog-row"><div><b>${esc(c.nickname)} · •••• ${esc(c.last4)}</b><small>${c.card_type==='EMPRESA'?esc(company(c.company_key))+' · corporativo':esc(c.owner_name||'Pessoal')} · ${esc(cardModeLabel(c))}${c.brand?' · '+esc(c.brand):''}${bankLabel(c)?' · '+esc(bankLabel(c)):''}${c.card_type==='EMPRESA'&&Array.isArray(c.shared_user_ids)&&c.shared_user_ids.length?' · compartilhado com '+c.shared_user_ids.length+' pessoa(s)':''}</small></div><div class="catalog-row-actions">${c.can_manage!==false?`<button class="btn" data-card-edit="${c.card_id}">Editar</button><button class="btn bad" data-card-del="${c.card_id}">Excluir</button>`:'<span class="chip">Compartilhado comigo</span>'}</div></div>`).join('')||'<div class="empty">Nenhum cartão cadastrado.</div>'}</div>`}else{const d=defs.find(x=>x.type===catalogTab);if(!d){catalogTab='cards';return renderCatalogs()}const rows=d.rows.filter(x=>!currentCompany()||x.company_key===currentCompany());panel=`<div class="catalog-panel"><div class="catalog-panel-head"><div class="grow"><h3>${d.label}</h3><small>${rows.length} cadastro(s) ativo(s)</small></div><button class="btn primary" data-add="${d.type}">+ Adicionar</button></div>${rows.map(x=>`<div class="catalog-row"><div><b>${esc(x.name)}</b><small>${esc(company(x.company_key))}${x.code?' · '+esc(x.code):''}${x.description?' · '+esc(x.description):''}</small></div><div class="catalog-row-actions"><button class="btn" data-cat-edit="${d.type}" data-id="${x[d.id]}">Editar</button><button class="btn bad" data-cat-del="${d.type}" data-id="${x[d.id]}">Excluir</button></div></div>`).join('')||'<div class="empty">Nenhum cadastro nesta seção.</div>'}</div>`}$('catalogGrid').innerHTML=`<div class="catalog-manager"><div class="catalog-tabs">${tabs}</div>${panel}</div>`;document.querySelectorAll('[data-cat-tab]').forEach(b=>b.onclick=()=>{catalogTab=b.dataset.catTab;renderCatalogs()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>catalogForm(b.dataset.add));document.querySelectorAll('[data-cat-edit]').forEach(b=>{b.onclick=()=>{const d=defs.find(x=>x.type===b.dataset.catEdit),item=d.rows.find(x=>String(x[d.id])===String(b.dataset.id));catalogForm(d.type,item)}});document.querySelectorAll('[data-cat-del]').forEach(b=>b.onclick=()=>deleteCatalog(b.dataset.catDel,b.dataset.id));if($('addPersonalCard'))$('addPersonalCard').onclick=()=>cardForm('PESSOAL');if($('addCompanyCard'))$('addCompanyCard').onclick=()=>cardForm('EMPRESA');document.querySelectorAll('[data-card-edit]').forEach(b=>b.onclick=()=>{const c=by(cards,b.dataset.cardEdit,'card_id');cardForm(c.card_type,c)});document.querySelectorAll('[data-card-del]').forEach(b=>b.onclick=()=>deleteCard(b.dataset.cardDel))}
async function refreshAdminData(){const boot=await api('/bootstrap'),eligible=await scheduleApi('/eligible-users');B=boot;B.users=eligible.users||[];if(!B.users.some(u=>String(u.id)===String(B.user.id)))B.users.unshift({id:B.user.id,email:B.user.email,name:B.user.name,profile:B.user.profile,entity_key:null});await reload();renderCatalogs()}
function cardForm(type,item=null){const brandList=['Visa','Mastercard','Elo','American Express','Hipercard'],currentBrand=String(item?.brand||''),knownBrand=brandList.some(x=>x.toLowerCase()===currentBrand.toLowerCase()),bankOptions=(banks||[]).map(b=>`<option value="${esc(b.bank_code)}">${esc(b.bank_code)} — ${esc(b.name)}</option>`).join(''),shared=new Set((item?.shared_user_ids||[]).map(String)),shareRows=(shareCandidates||[]).filter(u=>String(u.id)!==String(B.user.id)&&String(u.id)!==String(item?.created_by_user_id||''));$('modalTitle').textContent=item?'Editar cartão':type==='EMPRESA'?'Novo cartão da empresa':'Novo cartão pessoal';$('modalBody').innerHTML=`<div class="form">${type==='EMPRESA'?`<div class="field"><label>Empresa *</label><select id="cardCompany">${opts(B.companies,'key','name')}</select></div>`:''}<div class="field"><label>Apelido *</label><input id="cardNick" placeholder="Ex.: Itaú Black" value="${esc(item?.nickname||'')}"></div><div class="field"><label>Modalidade *</label><select id="cardPaymentMode"><option value="CREDITO">Crédito</option><option value="DEBITO">Débito</option><option value="AMBOS">Crédito e Débito</option></select></div><div class="field"><label>Número ou 4 finais *</label><input id="cardNumber" inputmode="numeric" autocomplete="off" placeholder="Número do cartão ou últimos 4 dígitos" value="${esc(item?.last4||'')}"><small>O sistema guarda somente os últimos 4 dígitos.</small></div><div class="field"><label>Banco / emissor</label><select id="cardBank"><option value="">Selecione o banco…</option>${bankOptions}<option value="__NEW__">+ Adicionar outro banco</option></select></div><div id="newBankWrap" class="field full hidden"><div class="form"><div class="field"><label>Código do banco *</label><input id="newBankCode" inputmode="numeric" maxlength="3" placeholder="Ex.: 260"></div><div class="field"><label>Nome do banco *</label><input id="newBankName" placeholder="Nome da instituição"></div></div><small>O banco será salvo e ficará disponível nos próximos cartões.</small></div><div class="field"><label>Bandeira</label><select id="cardBrand"><option value="">Selecione a bandeira…</option>${brandList.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}<option value="__OTHER__">Outra bandeira…</option></select></div><div id="otherBrandWrap" class="field hidden"><label>Outra bandeira</label><input id="otherBrand" placeholder="Nome da bandeira" value="${esc(!knownBrand?currentBrand:'')}"></div>${type==='EMPRESA'?`<div class="field full"><label>Quem pode usar este cartão?</label><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:7px;padding:10px;border:1px solid var(--line);border-radius:10px;background:#fafcff">${shareRows.map(u=>`<label style="display:flex;align-items:center;gap:7px"><input type="checkbox" data-card-share value="${u.id}" ${shared.has(String(u.id))?'checked':''}> <span>${esc(u.name)}</span></label>`).join('')||'<small>Nenhum outro sócio disponível.</small>'}</div><small>Somente as pessoas marcadas poderão selecionar este cartão em novas despesas. Você, como responsável pelo cartão, mantém acesso automaticamente.</small></div>`:'<div class="field full"><div class="payment-note"><b>Privado:</b> este cartão pessoal só aparecerá para você. Em despesas já registradas, outros usuários autorizados a ver a despesa verão apenas o apelido do cartão.</div></div>'}</div>`;$('modalActions').innerHTML='<button class="btn" id="modalClose">Cancelar</button><button class="btn primary" id="saveCard">Salvar</button>';showModal();if($('cardCompany')){$('cardCompany').value=item?.company_key||currentCompany()||B.companies[0]?.key||'';if(item)$('cardCompany').disabled=true}$('cardPaymentMode').value=String(item?.payment_mode||'AMBOS').toUpperCase();$('cardBank').value=(banks||[]).some(b=>String(b.bank_code)===String(item?.bank_code||''))?String(item.bank_code):'';$('cardBrand').value=knownBrand?brandList.find(x=>x.toLowerCase()===currentBrand.toLowerCase()):currentBrand?'__OTHER__':'';const toggleBank=()=>$('newBankWrap').classList.toggle('hidden',$('cardBank').value!=='__NEW__'),toggleBrand=()=>$('otherBrandWrap').classList.toggle('hidden',$('cardBrand').value!=='__OTHER__');$('cardBank').onchange=toggleBank;$('cardBrand').onchange=toggleBrand;toggleBank();toggleBrand();$('modalClose').onclick=hideModal;$('saveCard').onclick=async()=>{let bankCode=$('cardBank').value;if(bankCode==='__NEW__'){const code=digits($('newBankCode').value),name=$('newBankName').value.trim();if(code.length!==3)return alert('Informe o código do banco com 3 dígitos.');if(!name)return alert('Informe o nome do banco.');const br=await cardApi('/banks',{method:'POST',body:JSON.stringify({bank_code:code,name})});bankCode=br.bank?.bank_code||code}const brand=$('cardBrand').value==='__OTHER__'?$('otherBrand').value.trim():$('cardBrand').value,sharedIds=type==='EMPRESA'?[...document.querySelectorAll('[data-card-share]:checked')].map(x=>Number(x.value)):[];await cardApi('/cards',{method:'POST',body:JSON.stringify({card_id:item?.card_id||null,card_type:type,company_key:$('cardCompany')?.value||item?.company_key||null,nickname:$('cardNick').value,last4:$('cardNumber').value,brand:brand||null,bank_code:bankCode||null,payment_mode:$('cardPaymentMode').value,shared_user_ids:sharedIds})});hideModal();await reload();renderCatalogs();renderCardOptions();flash(item?'Cartão atualizado.':'Cartão cadastrado.')}}
async function deleteCard(id){if(!confirm('Excluir este cartão do cadastro? O histórico das despesas antigas será preservado.'))return;await cardApi('/cards?id='+encodeURIComponent(id),{method:'DELETE'});await reload();renderCatalogs();renderCardOptions();flash('Cartão excluído.')}
function catalogForm(type,item=null){const d=catalogDefs().find(x=>x.type===type),hasCode=['cost_center','project'].includes(type),hasDescription=type!=='payment_method';$('modalTitle').textContent=item?'Editar '+d.label.toLowerCase():'Novo cadastro';$('modalBody').innerHTML=`<div class="form"><div class="field"><label>Empresa *</label><select id="cCompany">${opts(B.companies,'key','name')}</select></div>${hasCode?`<div class="field"><label>Código</label><input id="cCode" value="${esc(item?.code||'')}"></div>`:''}<div class="field"><label>Nome *</label><input id="cName" value="${esc(item?.name||'')}"></div>${hasDescription?`<div class="field full"><label>Descrição</label><textarea id="cDescription">${esc(item?.description||'')}</textarea></div>`:''}</div>`;$('modalActions').innerHTML='<button class="btn" id="modalClose">Cancelar</button><button class="btn primary" id="saveCatalog">Salvar</button>';showModal();$('cCompany').value=item?.company_key||currentCompany()||B.companies[0]?.key||'';if(item)$('cCompany').disabled=true;$('modalClose').onclick=hideModal;$('saveCatalog').onclick=async()=>{const payload={company_key:$('cCompany').value,name:$('cName').value};if(item)payload[d.id]=item[d.id];if(hasCode)payload.code=$('cCode').value;if(hasDescription)payload.description=$('cDescription').value;await catalogApi('/'+type,{method:'POST',body:JSON.stringify(payload)});hideModal();await refreshAdminData();flash(item?'Cadastro atualizado.':'Cadastro criado.')}}
async function deleteCatalog(type,id){const d=catalogDefs().find(x=>x.type===type),item=d?.rows.find(x=>String(x[d.id])===String(id));if(!item||!confirm(`Excluir “${item.name}”? Ele deixará de aparecer nos novos lançamentos, mas o histórico será preservado.`))return;await catalogApi('/'+type+'?id='+encodeURIComponent(id),{method:'DELETE'});await refreshAdminData();flash('Cadastro excluído.')}
async function loadAudit(){if(!B.permissions.admin)return;const q=currentCompany()?'?company='+encodeURIComponent(currentCompany()):'',r=await api('/audit'+q);$('auditList').innerHTML=(r.audit||[]).slice(0,500).map(x=>`<div class="rowcard"><div><b>${esc(x.action)}</b><br><small>${esc(x.actor_email)} · ${esc(x.entity_type)} · ${esc(x.entity_id)}</small></div><small>${dt(x.created_at)}</small></div>`).join('')||'<div class="empty">Sem registros.</div>'}
