function exportExpenses(){const rows=filteredExpenses().map(x=>({Empresa:company(x.company_key),Data:dt(x.incurred_at),Pessoa:user(x.paid_by_user_id),Tipo:x.expense_type==='EVENTO'?'Evento':'Dia a dia',Descrição:x.description,Fornecedor:x.vendor_name||'','CNPJ/CPF':x.vendor_document||'','Valor solicitado':Number(x.requested_amount||0),'Valor aprovado':Number(x.approved_amount||0),Reembolsado:Number(x.reimbursed_amount||0),'Saldo pendente':Number(x.pending_amount||0),Reembolsável:x.reimbursable?'Sim':'Não',Cartão:expenseCardReportLabel(x),Status:labels[x.status]||x.status})),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Despesas');XLSX.writeFile(wb,'Despesas_Reembolsos_Livion.xlsx')}
function digits(v){return String(v||'').replace(/\D/g,'')}
function formatDocument(v){const n=digits(v).slice(0,14);if(n.length<=11){return n.replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d{1,2})$/,'.$1-$2')}return n.replace(/^(\d{2})(\d)/,'$1.$2').replace(/^(\d{2})\.(\d{3})(\d)/,'$1.$2.$3').replace(/\.(\d{3})(\d)/,'.$1/$2').replace(/(\d{4})(\d{1,2})$/,'$1-$2')}
function formatPhone(v){const n=digits(v).slice(0,11);if(n.length<=10)return n.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{4})(\d{1,4})$/,'$1-$2');return n.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{5})(\d{1,4})$/,'$1-$2')}
function formatCep(v){return digits(v).slice(0,8).replace(/^(\d{5})(\d)/,'$1-$2')}
function formatAccessKey(v){return digits(v).slice(0,44).replace(/(.{4})/g,'$1 ').trim()}
function formatCardNumber(v){return digits(v).slice(0,19).replace(/(.{4})/g,'$1 ').trim()}
function normalizedDocument(v){const n=digits(v);return n.length===11||n.length===14?n:String(v||'').trim()}
const BAD_FISCAL_LABEL=/INFORMA[CÇ][ÕO]ES?\s+DE\s+INTERESSE|CONTRIBUINTE|DOCUMENTO\s+AUXILIAR|CONSULTA\s+PELA\s+CHAVE|VALOR\s+PAGO\s*R\$?\s*:?\s*$/i;
function sanitizeFiscalResult(raw={}){const d={...raw};if(BAD_FISCAL_LABEL.test(String(d.establishment||'')))d.establishment='';if(d.payment_method&&!/(PIX|CR[EÉ]DITO|D[EÉ]BITO|DINHEIRO|BOLETO|CART[AÃ]O)/i.test(String(d.payment_method)))d.payment_method='';d.cnpj=digits(d.cnpj||'').slice(0,14);d.access_key=digits(d.access_key||'').slice(0,44);if(d.value!=null&&(!(Number(d.value)>0)||!Number.isFinite(Number(d.value))))d.value=null;return d}
function maskTarget(el){if(!el||el.tagName!=='INPUT'||el.type==='number'||el.type==='datetime-local'||el.type==='date')return;const sig=((el.id||'')+' '+(el.name||'')+' '+(el.placeholder||'')).toLowerCase();if(el.id==='fCnpj'||el.id==='eVendorDoc'||el.id==='eConsumerDoc'||/\b(cpf|cnpj)\b/.test(sig)){el.value=formatDocument(el.value);return}if(el.id==='fKey'||/chave.*acesso/.test(sig)){el.value=formatAccessKey(el.value);return}if(el.id==='cardNumber'){el.value=formatCardNumber(el.value);return}if(el.type==='tel'||/(telefone|celular|whatsapp|phone)/.test(sig)){el.value=formatPhone(el.value);return}if(/\bcep\b/.test(sig)){el.value=formatCep(el.value)}}
function bindStandardMasks(){document.addEventListener('input',e=>maskTarget(e.target));document.querySelectorAll('input').forEach(maskTarget)}
function parseKey(raw){const k=(String(raw||'').match(/\d{44}/)||[])[0];if(!k)return{};const aamm=k.slice(2,6),yy=Number(aamm.slice(0,2)),mm=aamm.slice(2,4);return{access_key:k,cnpj:k.slice(6,20),model:k.slice(20,22),series:String(Number(k.slice(22,25))),number:String(Number(k.slice(25,34))),year_month:`20${String(yy).padStart(2,'0')}-${mm}`}}
function brMoney(v){const m=String(v||'').match(/(?:R\$\s*)?([\d.]+,\d{2})/g);if(!m?.length)return null;const s=m[m.length-1].replace(/R\$\s*/i,'').replace(/\./g,'').replace(',','.');const n=Number(s);return Number.isFinite(n)?n:null}
function vendorCandidate(s){const v=String(s||'').replace(/\s+/g,' ').trim(),bad=/DOCUMENTO|AUXILIAR|NFC|NF-E|CNPJ|CPF|CONSUMIDOR|CHAVE|CUPOM|EXTRATO|SAT|SEFAZ|VIA CLIENTE|CR[EÉ]DITO|D[EÉ]BITO|VISA|MASTERCARD|ELO\b|AMEX|POS\s*[=: -]|DOC\s*[=: -]|VALOR|APP\b|AUTORIZA[CÇ][AÃ]O|NSU\b/i;if(v.length<4||v.length>90||bad.test(v)||/^\d/.test(v)||!/([A-Za-zÀ-ÿ].*){3}/.test(v))return'';const letters=(v.match(/[A-Za-zÀ-ÿ]/g)||[]).length;if(letters/Math.max(v.length,1)<.45)return'';return v}
